    sortUpdates(parseUpdates(updatesFixture).members, "newest")
      .slice(0, 10)
      .map(({ name }) => name),
  );
  const mps = page.getByRole("button", { name: "MPs", exact: true });
  const companies = page.getByRole("button", {
    name: "Companies",
    exact: true,
  });
