  await expect(mps).toBeFocused();
  await page.keyboard.press("Space");
  await expect(members).toBeVisible();
  await expect(mps).toBeFocused();
  await expect(mps).toHaveAttribute("aria-pressed", "true");
  expect(requests).toBe(initialRequests);
});

